#include "world/LootTable.h"
#include <iostream>
int main(){if(!LootTable::dropsAppleForRoll(BlockType::LEAVES,0)||LootTable::dropsAppleForRoll(BlockType::LEAVES,1)||LootTable::dropsAppleForRoll(BlockType::LEAVES,199)||!LootTable::dropsAppleForRoll(BlockType::LEAVES,200)||LootTable::dropsAppleForRoll(BlockType::DIRT,0)){std::cerr<<"apple roll boundary did not match 0.5% leaf-only behavior\n";return 1;}LootTable loot(1234),again(1234);int apples=0;for(int i=0;i<20000;++i){const bool a=loot.dropsApple(BlockType::LEAVES),b=again.dropsApple(BlockType::LEAVES);if(a!=b){std::cerr<<"seeded loot was not deterministic\n";return 1;}apples+=a?1:0;}if(apples<70||apples>130){std::cerr<<"leaf drop rate was not near 0.5%: "<<apples<<'\n';return 1;}for(int i=0;i<100;++i)if(loot.dropsApple(BlockType::DIRT)){std::cerr<<"non-leaf dropped an apple\n";return 1;}return 0;}
